        super(field, location);
    }

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * @param newPlants A list to receive newly born plants.
     * @param weather The current weather.
     */
    abstract public void act(int step, Weather weather);
}

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;
import java.util.function.Function;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 2022.02.xx 
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid. 
    private static final int DEFAULT_WIDTH = 120;
    // The default depth of the grid. 
    private static final int DEFAULT_DEPTH = 80;
    // The probability that a fox will be created in any given grid position.
    private static final double LION_CREATION_PROBABILITY = 0.01;
    // The probability that a rabbit will be created in any given grid position.
    private static final double DEER_CREATION_PROBABILITY = 0.02;    
    // The probability that a owl will be created in any given grid position.
    private static final double OWL_CREATION_PROBABILITY = 0.05;
    // The probability that a cat will be created in any given grid position.
    private static final double CAT_CREATION_PROBABILITY = 0.05;
    // The probability that a mouse will be created in any given grid position.
    private static final double MOUSE_CREATION_PROBABILITY = 0.04;    
    // The probability that a grass will be created in any given grid position.
    private static final double GRASS_CREATION_PROBABILITY = 0.4;    

    // List of animals in the field.
    private List<Animal> animals;
    // List of animals in the field.
    private List<Plant> plants;
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // The current weather of the simulation.
    private Weather weather;
    // A graphical view of the simulation.
    private SimulatorView view;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        animals = new ArrayList<>();
        plants = new ArrayList<>();
        field = new Field(depth, width);

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);
        configureViewColors();

        // Setup a valid starting point.
        reset();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;
        updateWeather();

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, step, weather);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born foxes and rabbits to the main lists.
        animals.addAll(newAnimals);

        // Let all plants act.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(step, weather);
            if(! plant.isAlive()) {
                it.remove();
            }
        }

        view.showStatus(step, field, weather);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        animals.clear();
        plants.clear();
        populate();
        updateWeather();

        // Show the starting state in the view.
        view.showStatus(step, field, weather);
    }

    /**
     * Randomly populate the field with Lions, Cats, Owls, Deers and mouses.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(tryPopulateAnimal(rand, LION_CREATION_PROBABILITY,
                                     location -> new Lion(true, field, location), row, col)) {
                    continue;
                }
                if(tryPopulateAnimal(rand, DEER_CREATION_PROBABILITY,
                                     location -> new Deer(true, field, location), row, col)) {
                    continue;
                }
                if(tryPopulateAnimal(rand, OWL_CREATION_PROBABILITY,
                                     location -> new Owl(true, field, location), row, col)) {
                    continue;
                }
                if(tryPopulateAnimal(rand, MOUSE_CREATION_PROBABILITY,
                                     location -> new Mouse(true, field, location), row, col)) {
                    continue;
                }
                if(tryPopulateAnimal(rand, CAT_CREATION_PROBABILITY,
                                     location -> new Cat(true, field, location), row, col)) {
                    continue;
                }
                tryPopulatePlant(rand, GRASS_CREATION_PROBABILITY,
                                 location -> new Grass(true, field, location), row, col);
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * 
     * 
     */
    private void updateWeather()
    {
        weather = Weather.random(Randomizer.getRandom());
    }

    /**
     * Configure display colors for each species.
     */
    private void configureViewColors()
    {
        view.setColor(Deer.class, Color.BLUE);
        view.setColor(Lion.class, Color.RED);
        view.setColor(Mouse.class, Color.YELLOW);
        view.setColor(Owl.class, Color.ORANGE);
        view.setColor(Cat.class, Color.PINK);
        view.setColor(Grass.class, Color.GREEN);
    }

    /**
     * Try to populate an animal into the given field location.
     */
    private boolean tryPopulateAnimal(Random rand, double probability,
                                      Function<Location, Animal> factory,
                                      int row, int col)
    {
        if(rand.nextDouble() <= probability) {
            animals.add(factory.apply(new Location(row, col)));
            return true;
        }
        return false;
    }

    /**
     * Try to populate a plant into the given field location.
     */
    private boolean tryPopulatePlant(Random rand, double probability,
                                     Function<Location, Plant> factory,
                                     int row, int col)
    {
        if(rand.nextDouble() <= probability) {
            plants.add(factory.apply(new Location(row, col)));
            return true;
        }
        return false;
    }
}

/**
 * Shared lifecycle and field-position state for all organisms in the
 * simulation.
 */
public abstract class Organism
{
    // Whether the organism is alive or not.
    private boolean alive;
    // The organism's field.
    private Field field;
    // The organism's position in the field.
    private Location location;

    /**
     * Create a new organism at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Organism(Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    protected final boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected final void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected final Location getLocation()
    {
        return location;
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected final void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected final Field getField()
    {
        return field;
    }
}

import java.util.List;
import java.util.Random;
import java.util.function.Consumer;
import java.util.function.Predicate;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2016.02.29 (2)
 */
public abstract class Animal extends Organism
{
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    // The animal's hurt level, when > 3 die
    private int burn;
    // The animal's gender.
    private final Gender gender;
    // The animal's age.
    private int age;
    // The animal's food level.
    private int foodLevel;


    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        super(field, location);
        burn = 0;
        gender = Gender.random(rand);
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param step The current step.
     * @param weather The current weather.
     */
    abstract public void act(List<Animal> newAnimals, int step, Weather weather);

    /**
     * Return the food value this animal provides when eaten.
     */
    abstract public int foodValue();

    /**
     * A factory for creating offspring at a specific location.
     */
    @FunctionalInterface
    protected interface OffspringFactory
    {
        Animal create(Field field, Location location);
    }

    /**
     * update the animal's burn status.
     * @param weather The current weather.
     */
    protected void updateBurnStatus(Weather weather)
    {
        if (burn > 0) {
            if (weather != Weather.RAINY) {
                burn();
            }
            else {
                recover();
            }
        }
    }

    /**
     * animal that step on fire will get burn and if burn status > 3 the animal will die 
     */
    protected void burn()
    {
        burn++;
        if (burn > 3) {
            setDead();
        }
    }

    /**
     * if weather is rainy the animal will recover and reset it's burn status to zero.
     */
    protected void recover()
    {
        burn = 0;
    }

    /**
     * @return the animal's gender
     */
    protected final Gender getGender()
    {
        return gender;
    }

    /**
     * Return adjacent locations around this animal.
     */
    protected final List<Location> adjacentLocations(int radius)
    {
        return getField().adjacentLocations(getLocation(), radius);
    }

    /**
     * Return free adjacent locations around this animal.
     */
    protected final List<Location> freeAdjacentLocations()
    {
        return getField().getFreeAdjacentLocations(getLocation());
    }

    /**
     * Find a free adjacent location around this animal.
     */
    protected final Location freeAdjacentLocation()
    {
        return getField().freeAdjacentLocation(getLocation());
    }

    /**
     * Move to the new location or die if there is nowhere to go.
     */
    protected final void moveToOrDie(Location newLocation)
    {
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            setDead();
        }
    }

    /**
     * Initialize the animal's age.
     */
    protected final void initializeAge(boolean randomAge, int maxAge)
    {
        if(randomAge) {
            age = rand.nextInt(maxAge);
        }
        else {
            age = 0;
        }
    }

    /**
     * Initialize the animal's food level.
     */
    protected final void initializeFoodLevel(boolean randomFoodLevel, int randomUpperBound,
                                             int initialFoodLevel)
    {
        if(randomFoodLevel) {
            foodLevel = rand.nextInt(randomUpperBound);
        }
        else {
            foodLevel = initialFoodLevel;
        }
    }

    /**
     * Increase the animal's age and kill it if it exceeds the limit.
     */
    protected final void incrementAge(int maxAge)
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Decrease the animal's food level and kill it if depleted.
     */
    protected final void decrementFoodLevel()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Adjust the animal's food level by the given amount.
     */
    protected final void changeFoodLevel(int delta)
    {
        foodLevel = foodLevel + delta;
    }

    /**
     * Return the animal's age.
     */
    protected final int getAge()
    {
        return age;
    }

    /**
     * Return the animal's food level.
     */
    protected final int getFoodLevel()
    {
        return foodLevel;
    }

    /**
     * Determine how many offspring are produced this step.
     */
    protected final int calculateBirths(int breedingAge, double breedingProbability,
                                        int maxLitterSize)
    {
        if(age >= breedingAge && rand.nextDouble() <= breedingProbability) {
            return rand.nextInt(maxLitterSize) + 1;
        }
        return 0;
    }

    /**
     * Add offspring into available adjacent locations.
     */
    protected final void addOffspring(List<Animal> newAnimals, int births,
                                      OffspringFactory offspringFactory)
    {
        Field field = getField();
        List<Location> free = freeAdjacentLocations();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location location = free.remove(0);
            newAnimals.add(offspringFactory.create(field, location));
        }
    }

    /**
     * Check whether a mate of the same species is nearby.
     */
    protected final boolean hasAdjacentMate(Class<? extends Animal> animalClass, int radius)
    {
        for(Location where : adjacentLocations(radius)) {
            Object animal = getField().getObjectAt(where);
            if(animalClass.isInstance(animal)) {
                Animal mate = (Animal) animal;
                if(mate.getGender() != getGender()) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Find the first adjacent location containing a matching target.
     */

     */
    protected final <T> Location findAdjacentLocation(Class<T> targetClass, int radius,
                                                      Predicate<T> predicate)
    {
        for(Location where : adjacentLocations(radius)) {
            Object target = getField().getObjectAt(where);
            if(targetClass.isInstance(target)) {
                T candidate = targetClass.cast(target);
                if(predicate.test(candidate)) {
                    return where;
                }
            }
        }
        return null;
    }

    /**
     * Apply an action to each adjacent matching target.
     */
    protected final <T> void forEachAdjacent(Class<T> targetClass, int radius,
                                             Consumer<T> action)
    {
        for(Location where : adjacentLocations(radius)) {
            Object target = getField().getObjectAt(where);
            if(targetClass.isInstance(target)) {
